-- Server-side operational intelligence rules for hardware, production, finance and the preserved margin/MDF vertical.
create or replace function public.refresh_project_hardware_alerts(p_project_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_uid uuid := (select auth.uid()); v_project public.projects%rowtype; v_rules jsonb; r jsonb; v_hid uuid; v_basis text; v_per numeric; v_fixed numeric; v_basis_qty numeric; v_req numeric; v_stock numeric; v_min numeric; v_supplier_missing boolean; v_price_missing boolean; begin if v_uid is null then raise exception 'authentication_required'; end if; select * into v_project from public.projects where id=p_project_id and user_id=v_uid; if not found then raise exception 'project_not_found'; end if; delete from public.operational_alerts where user_id=v_uid and entity_type='project' and entity_id=p_project_id and source='hardware_intelligence' and status='open'; delete from public.project_hardware_requirements where user_id=v_uid and project_id=p_project_id; v_rules:=coalesce((select construction_rules->'hardware_rules' from public.marcenaria_dna where user_id=v_uid),'[]'::jsonb); if jsonb_typeof(v_rules)<>'array' or jsonb_array_length(v_rules)=0 then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'HARDWARE_RULE_MISSING','ATENCAO','project',p_project_id,'hardware_intelligence','Regra de ferragens não configurada para este projeto.',jsonb_build_object('required_configuration','marcenaria_dna.construction_rules.hardware_rules'),'Configure as regras reais de ferragens antes de assumir quantidades.'); return; end if; for r in select value from jsonb_array_elements(v_rules) loop begin v_hid:=(r->>'hardware_id')::uuid; v_basis:=coalesce(r->>'basis',''); v_per:=nullif(r->>'quantity_per_unit','')::numeric; v_fixed:=nullif(r->>'fixed_quantity','')::numeric; exception when others then continue; end; if v_fixed is not null and v_fixed>0 then v_req:=v_fixed; elsif v_per is not null and v_per>0 then v_basis_qty:=case v_basis when 'doors' then coalesce(v_project.doors,0) when 'drawers' then coalesce(v_project.drawers,0) when 'modules' then coalesce(v_project.modules,0) else 0 end; if v_basis_qty<=0 then continue; end if; v_req:=v_basis_qty*v_per; else continue; end if; if not exists(select 1 from public.hardware_items where id=v_hid and user_id=v_uid and active) then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'HARDWARE_ITEM_NOT_CONFIGURED','ERRO','project',p_project_id,'hardware_intelligence','Uma regra aponta para uma ferragem que não está configurada.',jsonb_build_object('hardware_id',v_hid,'rule',r),'Cadastre a ferragem real antes de gerar compra.'); continue; end if; insert into public.project_hardware_requirements(user_id,project_id,hardware_id,quantity_required,source,rule_key) values(v_uid,p_project_id,v_hid,v_req,'rule',coalesce(r->>'key',v_basis)); select coalesce(s.quantity_on_hand,0),h.minimum_stock,(h.supplier_id is null),(h.unit_price is null) into v_stock,v_min,v_supplier_missing,v_price_missing from public.hardware_items h left join public.hardware_stock s on s.hardware_id=h.id and s.user_id=v_uid where h.id=v_hid and h.user_id=v_uid; if v_req>v_stock then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'HARDWARE_SHORTAGE','ATENCAO','project',p_project_id,'hardware_intelligence','Há ferragens insuficientes para este projeto.',jsonb_build_object('hardware_id',v_hid,'required',v_req,'stock',v_stock,'deficit',v_req-v_stock),'Compre a quantidade faltante ou revise a regra real.'); insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'PURCHASE_REQUIRED','ATENCAO','project',p_project_id,'hardware_intelligence','Existe compra de ferragem necessária para atender o projeto.',jsonb_build_object('hardware_id',v_hid,'quantity_to_buy',v_req-v_stock),'Crie a compra usando fornecedor e preço reais.'); elsif v_stock<=v_min and v_req>0 then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'STOCK_LOW','INFO','project',p_project_id,'hardware_intelligence','O estoque da ferragem está no mínimo configurado.',jsonb_build_object('hardware_id',v_hid,'stock',v_stock,'minimum_stock',v_min),'Avalie reposição antes da próxima produção.'); end if; if v_supplier_missing then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'SUPPLIER_MISSING','ATENCAO','project',p_project_id,'hardware_intelligence','A ferragem necessária não possui fornecedor configurado.',jsonb_build_object('hardware_id',v_hid),'Cadastre o fornecedor real do item.'); end if; if v_price_missing then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'HARDWARE_PRICE_MISSING','INFO','project',p_project_id,'hardware_intelligence','A ferragem necessária não possui preço real cadastrado.',jsonb_build_object('hardware_id',v_hid),'Cadastre o preço real para permitir análise de custo.'); end if; end loop; end; $$;
revoke execute on function public.refresh_project_hardware_alerts(uuid) from public,anon; grant execute on function public.refresh_project_hardware_alerts(uuid) to authenticated;

create or replace function public.refresh_project_production_alerts(p_project_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_uid uuid:=(select auth.uid()); r record; begin if v_uid is null then raise exception 'authentication_required'; end if; if not exists(select 1 from public.projects where id=p_project_id and user_id=v_uid) then raise exception 'project_not_found'; end if; delete from public.operational_alerts where user_id=v_uid and entity_type='project' and entity_id=p_project_id and source='production_intelligence' and status='open'; if not exists(select 1 from public.project_production_stages where user_id=v_uid and project_id=p_project_id) then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'PRODUCTION_RULE_MISSING','INFO','project',p_project_id,'production_intelligence','Não há etapas de produção configuradas para este projeto.',jsonb_build_object('project_id',p_project_id),'Configure etapas e prazos reais antes de avaliar atraso.'); return; end if; for r in select * from public.project_production_stages where user_id=v_uid and project_id=p_project_id and status<>'completed' loop if r.status='blocked' then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'PRODUCTION_BLOCKED','ERRO','project',p_project_id,'production_intelligence','Uma etapa de produção está bloqueada.',jsonb_build_object('stage_id',r.id,'stage',r.stage_name,'reason',r.blocked_reason),'Resolva o bloqueio ou registre a decisão operacional.'); end if; if r.responsible is null or btrim(r.responsible)='' then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'PRODUCTION_RESPONSIBLE_MISSING','ATENCAO','project',p_project_id,'production_intelligence','A etapa de produção não possui responsável configurado.',jsonb_build_object('stage_id',r.id,'stage',r.stage_name),'Defina o responsável real.'); end if; if r.due_at is not null and r.due_at<now() then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,case when lower(r.stage_key) like '%mont%' then 'ASSEMBLY_DELAY' else 'PRODUCTION_DELAY' end,'ERRO','project',p_project_id,'production_intelligence','Uma etapa operacional está atrasada.',jsonb_build_object('stage_id',r.id,'stage',r.stage_name,'due_at',r.due_at,'status',r.status),'Replaneje a etapa e registre o novo prazo real.'); elsif r.due_at is not null and r.due_at<=now()+interval '2 days' then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'DEADLINE_RISK','ATENCAO','project',p_project_id,'production_intelligence','Uma etapa está próxima do prazo configurado.',jsonb_build_object('stage_id',r.id,'stage',r.stage_name,'due_at',r.due_at),'Verifique capacidade e impedimentos antes do vencimento.'); end if; end loop; end; $$;
revoke execute on function public.refresh_project_production_alerts(uuid) from public,anon; grant execute on function public.refresh_project_production_alerts(uuid) to authenticated;

create or replace function public.refresh_project_financial_alerts(p_project_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_uid uuid:=(select auth.uid()); v_sale numeric; v_cost numeric; v_result numeric; v_margin numeric; v_min_margin numeric; v_overdue numeric; v_open_due numeric; v_complete boolean; begin if v_uid is null then raise exception 'authentication_required'; end if; if not exists(select 1 from public.projects where id=p_project_id and user_id=v_uid) then raise exception 'project_not_found'; end if; delete from public.operational_alerts where user_id=v_uid and entity_type='project' and entity_id=p_project_id and source='financial_intelligence' and status='open'; select sale_price into v_sale from public.project_sales where user_id=v_uid and project_id=p_project_id and status='sold'; select (material_cost+hardware_cost+labor_cost+coalesce(other_cost,0)),(sale_price is not null and material_cost is not null and hardware_cost is not null and labor_cost is not null) into v_cost,v_complete from public.project_cost_snapshots where user_id=v_uid and project_id=p_project_id; if not v_complete then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'PROFIT_NOT_CALCULABLE','INFO','project',p_project_id,'financial_intelligence','O lucro real ainda não pode ser calculado por falta de dados de custo.',jsonb_build_object('required',array['sale_price','material_cost','hardware_cost','labor_cost']),'Complete os custos reais registrados.'); elsif v_sale is null then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'SALE_RECORD_MISSING','ATENCAO','project',p_project_id,'financial_intelligence','O projeto possui custos, mas não há venda registrada como realizada.',jsonb_build_object('cost_snapshot_exists',true),'Registre a venda real do projeto.'); else select minimum_margin_pct into v_min_margin from public.marcenaria_dna where user_id=v_uid; v_result:=v_sale-v_cost; v_margin:=(v_result/nullif(v_sale,0))*100; if v_min_margin is not null and v_margin<v_min_margin then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,case when v_margin<(v_min_margin/2) then 'MARGIN_CRITICAL' else 'MARGIN_LOW' end,case when v_margin<(v_min_margin/2) then 'CRITICO' else 'ATENCAO' end,'project',p_project_id,'financial_intelligence','A margem do projeto está abaixo do mínimo configurado no DNA.',jsonb_build_object('revenue',v_sale,'cost',v_cost,'result',v_result,'margin_pct',v_margin,'minimum_margin_pct',v_min_margin),'Revise preço e custos reais antes de aceitar o projeto.'); end if; end if; select coalesce(sum(amount) filter(where received_at is null and due_at<now() and status='open'),0),coalesce(sum(amount) filter(where received_at is null and status='open'),0) into v_overdue,v_open_due from public.project_receivables where user_id=v_uid and project_id=p_project_id and status<>'cancelled'; if v_overdue>0 then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'RECEIPT_OVERDUE','ERRO','project',p_project_id,'financial_intelligence','Há recebimentos vencidos para este projeto.',jsonb_build_object('overdue_amount',v_overdue),'Faça a cobrança e registre o recebimento real.'); elsif v_open_due>0 and exists(select 1 from public.project_receivables where user_id=v_uid and project_id=p_project_id and status='open' and due_at<=now()+interval '2 days') then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_uid,'RECEIPT_DUE_SOON','INFO','project',p_project_id,'financial_intelligence','Há parcela próxima do vencimento.',jsonb_build_object('open_due_amount',v_open_due),'Acompanhe o recebimento e registre a baixa.'); end if; end; $$;
revoke execute on function public.refresh_project_financial_alerts(uuid) from public,anon; grant execute on function public.refresh_project_financial_alerts(uuid) to authenticated;

create or replace function public.refresh_project_operational_alerts(p_project_id uuid) returns integer language plpgsql security definer set search_path='' as $$ declare v_user uuid:=(select auth.uid()); v_project public.projects%rowtype; v_dna public.marcenaria_dna%rowtype; v_cost public.project_cost_snapshots%rowtype; v_count integer:=0; v_current_thickness numeric; v_min_margin numeric; v_current_margin numeric; v_total_cost numeric; begin if v_user is null then raise exception 'authentication_required'; end if; select * into v_project from public.projects where id=p_project_id and user_id=v_user; if not found then raise exception 'project_not_found'; end if; select * into v_dna from public.marcenaria_dna where user_id=v_user; select * into v_cost from public.project_cost_snapshots where user_id=v_user and project_id=p_project_id; delete from public.operational_alerts where user_id=v_user and entity_type='project' and entity_id=p_project_id and status='open' and source='operational_intelligence'; if v_dna.user_id is null then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_user,'DNA_NOT_CONFIGURED','INFO','project',p_project_id,'operational_intelligence','DNA da marcenaria não está configurado. Nenhuma regra comercial ou técnica foi inventada.','{"missing":"marcenaria_dna"}'::jsonb,'Configurar DNA da marcenaria'); v_count:=v_count+1; else v_min_margin:=v_dna.minimum_margin_pct; if v_cost.sale_price is not null and v_cost.sale_price>0 and v_cost.material_cost is not null and v_cost.hardware_cost is not null and v_cost.labor_cost is not null then v_total_cost:=coalesce(v_cost.material_cost,0)+coalesce(v_cost.hardware_cost,0)+coalesce(v_cost.labor_cost,0)+coalesce(v_cost.other_cost,0); v_current_margin:=((v_cost.sale_price-v_total_cost)/v_cost.sale_price)*100; if v_min_margin is not null and v_current_margin<v_min_margin then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_user,'LOW_MARGIN','ATENCAO','project',p_project_id,'operational_intelligence','Margem real calculada está abaixo do mínimo definido no DNA.',jsonb_build_object('configured_margin',v_min_margin,'current_margin',round(v_current_margin,2),'sale_price',v_cost.sale_price,'total_cost',v_total_cost),'Revisar custos e orçamento'); v_count:=v_count+1; end if; else insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_user,'MARGIN_DATA_INSUFFICIENT','INFO','project',p_project_id,'operational_intelligence','Dados insuficientes para calcular margem real.',jsonb_build_object('required','sale_price,material_cost,hardware_cost,labor_cost'),'Informar custos reais e preço de venda'); v_count:=v_count+1; end if; if v_dna.standard_mdf_thickness_mm is not null then v_current_thickness:=null; if v_project.external_material ~ 'mdf[0-9]+' then v_current_thickness:=substring(v_project.external_material from 'mdf([0-9]+)')::numeric; end if; if v_current_thickness is not null and v_current_thickness<>v_dna.standard_mdf_thickness_mm then insert into public.operational_alerts(user_id,alert_type,severity,entity_type,entity_id,source,message,evidence,suggested_action) values(v_user,'MDF_THICKNESS_MISMATCH','ATENCAO','project',p_project_id,'operational_intelligence','A espessura do MDF externo do projeto diverge do padrão cadastrado no DNA.',jsonb_build_object('standard_thickness_mm',v_dna.standard_mdf_thickness_mm,'project_thickness_mm',v_current_thickness,'material',v_project.external_material),'Revisar material do projeto'); v_count:=v_count+1; end if; end if; end if; perform public.refresh_project_hardware_alerts(p_project_id); perform public.refresh_project_production_alerts(p_project_id); perform public.refresh_project_financial_alerts(p_project_id); return v_count; end; $$;
revoke execute on function public.refresh_project_operational_alerts(uuid) from public,anon; grant execute on function public.refresh_project_operational_alerts(uuid) to authenticated;